1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14	)
15	
16	// Point 是一条序列上某个时间戳的采样值。
17	type Point struct {
18		Timestamp int64   `json:"timestamp"`
19		Value     float64 `json:"value"`
20	}
21	
22	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
23	type SeriesView struct {
24		Name   string            `json:"name"`
25		Labels map[string]string `json:"labels"`
26		Points []Point           `json:"points"`
27	}
28	
29	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
30	type QuerySeries struct {
31		Name    string            `json:"name"`
32		Labels  map[string]string `json:"labels"`
33		Count   int               `json:"count"`
34		Average float64           `json:"average"`
35	}
36	
37	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
38	type QueryResult struct {
39		Status string        `json:"status"`
40		Op     string        `json:"op"`
41		Series []QuerySeries `json:"series"`
42	}
43	
44	// BatchResult 是一批采样点写入成功后的结果。
45	type BatchResult struct {
46		Status     string       `json:"status"`
47		Added      int          `json:"added"`
48		Duplicates int          `json:"duplicates"`
49		Series     []SeriesView `json:"series"`
50	}
51	
52	// SeriesRef 标识一条序列：指标名加完整标签集合。
53	// 缺少某个标签与该标签值为空字符串属于不同序列。
54	type SeriesRef struct {
55		Name   string            `json:"name"`
56		Labels map[string]string `json:"labels"`
57	}
58	
59	// Conflict 描述同一序列同一时间戳已存在不同的值。
60	type Conflict struct {
61		Series    SeriesRef `json:"series"`
62		Timestamp int64     `json:"timestamp"`
63		Existing  float64   `json:"existing"`
64		Submitted float64   `json:"submitted"`
65	}
66	
67	// LineError 是一行（一批）输入失败后的结构化结果。
68	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
69	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
70	type LineError struct {
71		Status   string    `json:"status"`
72		Line     int       `json:"line,omitempty"`
73		Index    int       `json:"index,omitempty"`
74		Error    string    `json:"error"`
75		Conflict *Conflict `json:"conflict,omitempty"`
76	}
77	
78	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
79	type MetricStore struct {
80		series map[seriesID]*storedSeries
81	}
82	
83	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
84	type seriesID struct {
85		name string
86		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
87		sig string
88	}
89	
90	type storedSeries struct {
91		ref    SeriesRef
92		points map[int64]float64
93	}
94	
95	// NewMetricStore 创建一个空的指标存储。
96	func NewMetricStore() *MetricStore {
97		return &MetricStore{series: make(map[seriesID]*storedSeries)}
98	}
99	
100	func sortedKeys(m map[string]string) []string {
101		keys := make([]string, 0, len(m))
102		for k := range m {
103			keys = append(keys, k)
104		}
105		sort.Strings(keys)
106		return keys
107	}
108	
109	func makeSeriesID(name string, labels map[string]string) seriesID {
110		var b strings.Builder
111		for _, k := range sortedKeys(labels) {
112			v := labels[k]
113			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
114		}
115		return seriesID{name: name, sig: b.String()}
116	}
117	
118	// labelPair 是标签键值对字典序比较的单元。
119	type labelPair struct {
120		Key, Value string
121	}
122	
123	func sortedPairs(labels map[string]string) []labelPair {
124		keys := sortedKeys(labels)
125		pairs := make([]labelPair, len(keys))
126		for i, k := range keys {
127			pairs[i] = labelPair{Key: k, Value: labels[k]}
128		}
129		return pairs
130	}
131	
132	func compareLabelPairs(a, b []labelPair) int {
133		n := len(a)
134		if len(b) < n {
135			n = len(b)
136		}
137		for i := 0; i < n; i++ {
138			if a[i].Key != b[i].Key {
139				return strings.Compare(a[i].Key, b[i].Key)
140			}
141			if a[i].Value != b[i].Value {
142				return strings.Compare(a[i].Value, b[i].Value)
143			}
144		}
145		switch {
146		case len(a) < len(b):
147			return -1
148		case len(a) > len(b):
149			return 1
150		}
151		return 0
152	}
153	
154	var (
155		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
156		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
157	)
158	
159	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
160	// 成功时返回 BatchResult 或 *QueryResult；失败返回 *LineError（Index 始终为零）。
161	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
162		top, ok, lerr := decodeTopValue(line)
163		if lerr != nil {
164			return nil, lerr
165		}
166		switch ok {
167		case '[':
168			var items []json.RawMessage
169			if err := json.Unmarshal(top, &items); err != nil {
170				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
171			}
172			return s.ingestItems(items)
173		case '{':
174			return s.queryFromObject(top)
175		default:
176			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
177		}
178	}
179	
180	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
181	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
182	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
183		top, ok, lerr := decodeTopValue(line)
184		if lerr != nil {
185			return nil, lerr
186		}
187		if ok != '[' {
188			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
189		}
190		var items []json.RawMessage
191		if err := json.Unmarshal(top, &items); err != nil {
192			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
193		}
194		return s.ingestItems(items)
195	}
196	
197	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
198	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
199		top, ok, lerr := decodeTopValue(line)
200		if lerr != nil {
201			return nil, lerr
202		}
203		if ok != '{' {
204			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
205		}
206		return s.queryFromObject(top)
207	}
208	
209	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
210	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
211	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
212		dec := json.NewDecoder(strings.NewReader(line))
213		var top json.RawMessage
214		if err := dec.Decode(&top); err != nil {
215			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
216		}
217		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
218		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
219			if err == nil {
220				err = fmt.Errorf("unexpected content after the JSON value")
221			}
222			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
223		}
224		trimmed := strings.TrimSpace(string(top))
225		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
226			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
227		}
228		return top, trimmed[0], nil
229	}
230	
231	type parsedSample struct {
232		name   string
233		ts     int64
234		value  float64
235		labels map[string]string
236	}
237	
238	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
239	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
240	func parseSample(raw json.RawMessage) (parsedSample, error) {
241		var p parsedSample
242		p.labels = map[string]string{}
243		dec := json.NewDecoder(bytes.NewReader(raw))
244		dec.UseNumber()
245	
246		tok, err := dec.Token()
247		if err != nil {
248			return p, err
249		}
250		if d, ok := tok.(json.Delim); !ok || d != '{' {
251			return p, fmt.Errorf("each sample must be a JSON object")
252		}
253	
254		present := make(map[string]bool)
255		for dec.More() {
256			keyTok, err := dec.Token()
257			if err != nil {
258				return p, err
259			}
260			key := keyTok.(string)
261			switch key {
262			case "name", "timestamp", "value", "labels":
263			default:
264				return p, fmt.Errorf("unknown field %q", key)
265			}
266			if present[key] {
267				return p, fmt.Errorf("duplicate field %q", key)
268			}
269			present[key] = true
270	
271			switch key {
272			case "name":
273				t, err := dec.Token()
274				if err != nil {
275					return p, err
276				}
277				s, ok := t.(string)
278				if !ok {
279					return p, fmt.Errorf(`field "name" must be a string`)
280				}
281				if s == "" {
282					return p, fmt.Errorf(`field "name" must be a non-empty string`)
283				}
284				p.name = s
285			case "timestamp":
286				n, err := nextJSONNumber(dec, "timestamp")
287				if err != nil {
288					return p, err
289				}
290				v, err := parseJSONInt(n)
291				if err != nil {
292					return p, fmt.Errorf(`field "timestamp": %s`, err)
293				}
294				p.ts = v
295			case "value":
296				n, err := nextJSONNumber(dec, "value")
297				if err != nil {
298					return p, err
299				}
300				v, err := parseFiniteFloat(n)
301				if err != nil {
302					return p, fmt.Errorf(`field "value": %s`, err)
303				}
304				p.value = v
305			case "labels":
306				t, err := dec.Token()
307				if err != nil {
308					return p, err
309				}
310				d, ok := t.(json.Delim)
311				if !ok || d != '{' {
312					return p, fmt.Errorf(`field "labels" must be an object of string keys to string values`)
313				}
314				labels := map[string]string{}
315				for dec.More() {
316					labelKeyTok, err := dec.Token()
317					if err != nil {
318						return p, err
319					}
320					labelKey := labelKeyTok.(string)
321					if labelKey == "" {
322						return p, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
323					}
324					valTok, err := dec.Token()
325					if err != nil {
326						return p, err
327					}
328					labelVal, ok := valTok.(string)
329					if !ok {
330						return p, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
331					}
332					if _, dup := labels[labelKey]; dup {
333						return p, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
334					}
335					labels[labelKey] = labelVal
336				}
337				if _, err := dec.Token(); err != nil { // 消耗 '}'
338					return p, err
339				}
340				p.labels = labels
341			}
342		}
343		if _, err := dec.Token(); err != nil { // 消耗 '}'
344			return p, err
345		}
346		if _, err := dec.Token(); err != io.EOF {
347			if err == nil {
348				return p, fmt.Errorf("unexpected content after the sample object")
349			}
350			return p, err
351		}
352	
353		for _, field := range []string{"name", "timestamp", "value"} {
354			if !present[field] {
355				return p, fmt.Errorf("missing required field %q", field)
356			}
357		}
358		return p, nil
359	}
360	
361	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
362		t, err := dec.Token()
363		if err != nil {
364			return "", err
365		}
366		n, ok := t.(json.Number)
367		if !ok {
368			return "", fmt.Errorf(`field %q must be a JSON number`, field)
369		}
370		return n, nil
371	}
372	
373	func parseJSONInt(n json.Number) (int64, error) {
374		s := string(n)
375		if !jsonIntegerRE.MatchString(s) {
376			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
377		}
378		v, err := strconv.ParseInt(s, 10, 64)
379		if err != nil {
380			return 0, fmt.Errorf("must be within int64 range")
381		}
382		return v, nil
383	}
384	
385	func parseFiniteFloat(n json.Number) (float64, error) {
386		s := string(n)
387		if !jsonNumberRE.MatchString(s) {
388			return 0, fmt.Errorf("must be a JSON number")
389		}
390		v, err := strconv.ParseFloat(s, 64)
391		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
392			return 0, fmt.Errorf("must be a finite number representable as float64")
393		}
394		return v, nil
395	}
396	
397	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
398	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
399		type pending struct {
400			id  seriesID
401			ref SeriesRef
402			ts  int64
403			val float64
404		}
405	
406		added := 0
407		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
408		seen := make(map[seriesID]map[int64]float64)
409		// 仅记录需要落盘的新增点；校验全部通过后才提交。
410		commits := make([]pending, 0, len(items))
411	
412		failAt := func(index int, msg string) *LineError {
413			return &LineError{Status: "error", Index: index, Error: msg}
414		}
415		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
416			return &LineError{
417				Status: "error",
418				Index:  index,
419				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
420					ref, ts, formatFloat(existing), formatFloat(submitted)),
421				Conflict: &Conflict{
422					Series:    ref,
423					Timestamp: ts,
424					Existing:  existing,
425					Submitted: submitted,
426				},
427			}
428		}
429	
430		for i, item := range items {
431			pos := i + 1
432			p, err := parseSample(item)
433			if err != nil {
434				return nil, failAt(pos, err.Error())
435			}
436	
437			id := makeSeriesID(p.name, p.labels)
438			ref := SeriesRef{Name: p.name, Labels: p.labels}
439	
440			if byTS, ok := seen[id]; ok {
441				if old, ok := byTS[p.ts]; ok {
442					if old != p.value {
443						return nil, conflictAt(pos, ref, p.ts, old, p.value)
444					}
445					// 同批内重复出现且数值相同：重复，成功忽略。
446					continue
447				}
448			}
449			if sr, ok := s.series[id]; ok {
450				if old, ok := sr.points[p.ts]; ok {
451					if old != p.value {
452						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
453					}
454					// 与此前批次已写入的值相同：重复，成功忽略。
455					if seen[id] == nil {
456						seen[id] = map[int64]float64{}
457					}
458					seen[id][p.ts] = p.value
459					continue
460				}
461			}
462	
463			added++
464			if seen[id] == nil {
465				seen[id] = map[int64]float64{}
466			}
467			seen[id][p.ts] = p.value
468			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
469		}
470	
471		// 全部采样点合法且无冲突，原子提交本批新增点。
472		for _, c := range commits {
473			sr := s.series[c.id]
474			if sr == nil {
475				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
476				s.series[c.id] = sr
477			}
478			sr.points[c.ts] = c.val
479		}
480	
481		return s.snapshot(added, len(items)-added), nil
482	}
483	
484	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
485	func formatFloat(v float64) string {
486		return strconv.FormatFloat(v, 'g', -1, 64)
487	}
488	
489	type parsedQuery struct {
490		name   string
491		start  int64
492		end    int64
493		labels map[string]string
494	}
495	
496	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
497	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
498		q, err := parseQuery(raw)
499		if err != nil {
500			return nil, &LineError{Status: "error", Error: err.Error()}
501		}
502		if q.start > q.end {
503			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
504				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
505		}
506		return s.runQuery(q), nil
507	}
508	
509	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
510	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
511	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
512		var q parsedQuery
513		dec := json.NewDecoder(bytes.NewReader(raw))
514		dec.UseNumber()
515	
516		tok, err := dec.Token()
517		if err != nil {
518			return q, err
519		}
520		if d, ok := tok.(json.Delim); !ok || d != '{' {
521			return q, fmt.Errorf("each query must be a JSON object")
522		}
523	
524		present := make(map[string]bool)
525		for dec.More() {
526			keyTok, err := dec.Token()
527			if err != nil {
528				return q, err
529			}
530			key := keyTok.(string)
531			switch key {
532			case "op", "name", "start", "end", "labels":
533			default:
534				return q, fmt.Errorf("unknown field %q", key)
535			}
536			if present[key] {
537				return q, fmt.Errorf("duplicate field %q", key)
538			}
539			present[key] = true
540	
541			switch key {
542			case "op":
543				t, err := dec.Token()
544				if err != nil {
545					return q, err
546				}
547				op, ok := t.(string)
548				if !ok {
549					return q, fmt.Errorf(`field "op" must be a string`)
550				}
551				if op != "query" {
552					return q, fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
553				}
554			case "name":
555				t, err := dec.Token()
556				if err != nil {
557					return q, err
558				}
559				name, ok := t.(string)
560				if !ok {
561					return q, fmt.Errorf(`field "name" must be a string`)
562				}
563				if name == "" {
564					return q, fmt.Errorf(`field "name" must be a non-empty string`)
565				}
566				q.name = name
567			case "start", "end":
568				n, err := nextJSONNumber(dec, key)
569				if err != nil {
570					return q, err
571				}
572				v, err := parseJSONInt(n)
573				if err != nil {
574					return q, fmt.Errorf(`field %q: %s`, key, err)
575				}
576				if key == "start" {
577					q.start = v
578				} else {
579					q.end = v
580				}
581			case "labels":
582				t, err := dec.Token()
583				if err != nil {
584					return q, err
585				}
586				d, ok := t.(json.Delim)
587				if !ok || d != '{' {
588					return q, fmt.Errorf(`field "labels" must be an object of non-empty string keys to string values`)
589				}
590				labels := map[string]string{}
591				for dec.More() {
592					labelKeyTok, err := dec.Token()
593					if err != nil {
594						return q, err
595					}
596					labelKey := labelKeyTok.(string)
597					if labelKey == "" {
598						return q, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
599					}
600					valTok, err := dec.Token()
601					if err != nil {
602						return q, err
603					}
604					labelVal, ok := valTok.(string)
605					if !ok {
606						return q, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
607					}
608					if _, dup := labels[labelKey]; dup {
609						return q, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
610					}
611					labels[labelKey] = labelVal
612				}
613				if _, err := dec.Token(); err != nil { // 消耗 '}'
614					return q, err
615				}
616				q.labels = labels
617			}
618		}
619		if _, err := dec.Token(); err != nil { // 消耗 '}'
620			return q, err
621		}
622		if _, err := dec.Token(); err != io.EOF {
623			if err == nil {
624				return q, fmt.Errorf("unexpected content after the query object")
625			}
626			return q, err
627		}
628	
629		for _, field := range []string{"op", "name", "start", "end"} {
630			if !present[field] {
631				return q, fmt.Errorf("missing required field %q", field)
632			}
633		}
634		return q, nil
635	}
636	
637	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
638	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
639	func labelsMatch(want, stored map[string]string) bool {
640		for k, v := range want {
641			got, ok := stored[k]
642			if !ok || got != v {
643				return false
644			}
645		}
646		return true
647	}
648	
649	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
650	// 结果沿用 snapshot 的序列排序；无区间内点的序列不列出。
651	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
652		matched := make([]*storedSeries, 0)
653		for _, sr := range s.series {
654			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
655				continue
656			}
657			has := false
658			for ts := range sr.points {
659				if ts >= q.start && ts <= q.end {
660					has = true
661					break
662				}
663			}
664			if has {
665				matched = append(matched, sr)
666			}
667		}
668		sort.Slice(matched, func(i, j int) bool {
669			if matched[i].ref.Name != matched[j].ref.Name {
670				return matched[i].ref.Name < matched[j].ref.Name
671			}
672			return compareLabelPairs(sortedPairs(matched[i].ref.Labels), sortedPairs(matched[j].ref.Labels)) < 0
673		})
674	
675		out := make([]QuerySeries, 0, len(matched))
676		for _, sr := range matched {
677			tsList := make([]int64, 0, len(sr.points))
678			for ts := range sr.points {
679				if ts >= q.start && ts <= q.end {
680					tsList = append(tsList, ts)
681				}
682			}
683			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
684			values := make([]float64, len(tsList))
685			for i, ts := range tsList {
686				values[i] = sr.points[ts]
687			}
688			labels := make(map[string]string, len(sr.ref.Labels))
689			for k, v := range sr.ref.Labels {
690				labels[k] = v
691			}
692			out = append(out, QuerySeries{
693				Name:    sr.ref.Name,
694				Labels:  labels,
695				Count:   len(values),
696				Average: finiteMean(values),
697			})
698		}
699		return &QueryResult{Status: "ok", Op: "query", Series: out}
700	}
701	
702	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
703	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
704	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
705	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
706	// 只有一个点时结果就是该点的值。
707	func finiteMean(values []float64) float64 {
708		sum := new(big.Rat)
709		r := new(big.Rat)
710		for _, v := range values {
711			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
712			sum.Add(sum, r.SetFloat64(v))
713		}
714		sum.Quo(sum, r.SetInt64(int64(len(values))))
715		return ratToFloat64NearestEven(sum)
716	}
717	
718	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
719	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
720	func ratToFloat64NearestEven(x *big.Rat) float64 {
721		if x.Sign() == 0 {
722			return 0
723		}
724		num := new(big.Int).Set(x.Num())
725		den := x.Denom()
726		neg := num.Sign() < 0
727		if neg {
728			num.Neg(num)
729		}
730	
731		// e 满足 2^e <= num/den < 2^(e+1)。
732		e := floorLog2Rat(num, den)
733		var m *big.Int
734		scale := 0
735		if e >= -1022 {
736			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
737			scale = e - 52
738			m = roundScaledRatio(num, den, scale)
739			if m.BitLen() == 54 {
740				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
741				m.Rsh(m, 1)
742				scale++
743			}
744		} else {
745			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
746			scale = -1074
747			m = roundScaledRatio(num, den, scale)
748		}
749		// m < 2^53，可以精确放入 int64 与 float64。
750		f := math.Ldexp(float64(m.Int64()), scale)
751		if neg {
752			return -f
753		}
754		return f
755	}
756	
757	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
758	func floorLog2Rat(num, den *big.Int) int {
759		k := num.BitLen() - den.BitLen()
760		var t big.Int
761		if k >= 0 {
762			t.Lsh(den, uint(k))
763			if num.Cmp(&t) >= 0 {
764				return k
765			}
766			return k - 1
767		}
768		t.Lsh(num, uint(-k))
769		if t.Cmp(den) >= 0 {
770			return k
771		}
772		return k - 1
773	}
774	
775	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
776	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
777		n := new(big.Int).Set(num)
778		d := new(big.Int).Set(den)
779		if scale >= 0 {
780			d.Lsh(d, uint(scale))
781		} else {
782			n.Lsh(n, uint(-scale))
783		}
784		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
785		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
786		case 1:
787			q.Add(q, big.NewInt(1))
788		case 0:
789			if q.Bit(0) == 1 {
790				q.Add(q, big.NewInt(1))
791			}
792		}
793		return q
794	}
795	
796	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
797	func (r SeriesRef) String() string {
798		var b strings.Builder
799		b.WriteString(r.Name)
800		b.WriteByte('{')
801		for i, p := range sortedPairs(r.Labels) {
802			if i > 0 {
803				b.WriteByte(',')
804			}
805			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
806		}
807		b.WriteByte('}')
808		return b.String()
809	}
810	
811	// snapshot 生成按规范排序的全部序列视图：先按指标名，再按标签键值对字典序，
812	// 序列内按时间戳升序。
813	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
814		views := make([]SeriesView, 0, len(s.series))
815		for _, sr := range s.series {
816			tsList := make([]int64, 0, len(sr.points))
817			for ts := range sr.points {
818				tsList = append(tsList, ts)
819			}
820			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
821			points := make([]Point, len(tsList))
822			for i, ts := range tsList {
823				points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
824			}
825			labels := make(map[string]string, len(sr.ref.Labels))
826			for k, v := range sr.ref.Labels {
827				labels[k] = v
828			}
829			views = append(views, SeriesView{Name: sr.ref.Name, Labels: labels, Points: points})
830		}
831		sort.Slice(views, func(i, j int) bool {
832			if views[i].Name != views[j].Name {
833				return views[i].Name < views[j].Name
834			}
835			return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
836		})
837		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
838	}
839

